arguments.command:
cd /work && python3 << 'EOF'
import pandas as pd, numpy as np
tr = pd.read_csv('b3_pvk_stack_pin_train.csv')
po = pd.read_csv('b3_pvk_stack_pin_pool.csv')
cols = ['substrate','etl','htl','backcontact','deposition']
y = tr['target']
sm = 20  # smoothing
# Build component-level stats
stats = {}
for c in cols:
    for _,i_row in tr.iterrows():
        v = str(i_row[c]).replace('∣','|')
        for part in v.split('|'):
            for sub in part.split(';'):
                sub = sub.strip()
                if not sub: continue
                stats.setdefault((c,sub), []).append(i_row['target'])
def lookup(c, val):
    vals = []
    for part in str(val).replace('∣','|').split('|'):
        for sub in part.split(';'):
            s=sub.strip()
            if (c,s) in stats:
                vals.append(np.mean(stats[c,s]) )
    return np.mean(vals) if vals else y.mean()
# per candidate: mean of lookups
for i,row in po.iterrows():
    vals = [lookup(c, row[c]) for c in cols]
    po.loc[i,'stat'] = np.mean(vals)
po['grank'] = po['stat'].rank(ascending=False)
print(po.sort_values('grank').head(15)[['candidate_id','substrate','etl','htl','backcontact','deposition','stat']].to_string())
EOF

